(()=>{"use strict";var e=window.flarum.admin.app,t=window.flarum.common.extenders;e.initializers.add("peopleinside-admin-css",(()=>{e.translator.add("peopleinside-admin-css",{admin:{custom_css_label:"Custom Admin CSS",custom_css_help:"Insert custom CSS rules to style the Flarum administration backend. Use with caution, as invalid CSS may affect the admin interface layout."}})}));var r=[new t.Admin().setting((()=>({setting:"peopleinside-admin-css.custom_css",label:e.translator.trans("peopleinside-admin-css.admin.custom_css_label",{},!0),help:e.translator.trans("peopleinside-admin-css.admin.custom_css_help",{},!0),type:"textarea"})),10)];window.flarum=window.flarum||{},window.flarum.extensions=window.flarum.extensions||{},window.flarum.extensions["peopleinside/flarum-ext-admin-css"]={default:r}})();
